    if groups.len() < 2 {
        return true;
    }

    let (offset, len) = (groups[0][0], groups[0][1]);
    let mut prev_start = offset;
    let mut prev_end = offset + len;

    for g in &groups[1..] {
        let start = g[0];
        let end = g[0] + g[1];

        if start < prev_start || end < prev_end {
            return false;
        }

        prev_start = start;
        prev_end = end;
    }
    true
}
